examples.code:
#include <syncstream>
#include <sstream>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::ostringstream sink;
    {
        std::syncbuf buffer{sink.rdbuf()};
        assert(buffer.get_wrapped() == sink.rdbuf());
        auto allocator = buffer.get_allocator();
        (void)allocator;
        buffer.sputn("hello", 5);
        assert(buffer.emit());
        assert(sink.str() == "hello");
        buffer.set_emit_on_sync(true);
        buffer.sputc('!');
        assert(buffer.pubsync() == 0);
        std::syncbuf other{sink.rdbuf()};
        other = std::move(buffer);
        other.swap(buffer);
        std::swap(other, buffer);
    }
    {
        std::osyncstream output{sink};
        assert(output.rdbuf());
        output << " world" << std::emit_on_flush << std::flush_emit;
    }
    assert(sink.str().find("world") != std::string::npos);
}
